INSERT INTO rust_challenge_days (day_number, challenge_date, phase, week_number, week_focus, daily_task, dsa_rep) VALUES
(9, '2026-09-21', 1, 2, 'Finish the memory allocator — free lists and alignment', 'Implement memory alignment logic (`align_up`) and the `alloc` method for the free list, handling basic block splitting. *(Resource: [Rust std::alloc::Layout](https://doc.rust-lang.org/std/alloc/struct.Layout.html))*', 'Daily DSAR rep: Arrays & String manipulation. (e.g. Reverse string, valid palindrome)'),
(10, '2026-09-22', 1, 2, 'Finish the memory allocator — free lists and alignment', 'Implement the `dealloc` method and block coalescing (merging adjacent free blocks to prevent fragmentation). *(Resource: [Writing an OS in Rust: Free List Allocator implementation](https://os.phil-opp.com/allocator-designs/#free-list))*', 'Daily DSAR rep: Arrays & String manipulation. (e.g. Reverse string, valid palindrome)'),
(11, '2026-09-23', 1, 2, 'Finish the memory allocator — free lists and alignment', 'Implement the `GlobalAlloc` trait for the allocator, wrap it in a `spin::Mutex` to make it thread-safe. *(Resource: [Rust std::alloc::GlobalAlloc](https://doc.rust-lang.org/std/alloc/trait.GlobalAlloc.html))*', 'Daily DSAR rep: Arrays & String manipulation. (e.g. Reverse string, valid palindrome)'),
(12, '2026-09-24', 1, 2, 'Finish the memory allocator — free lists and alignment', 'Write comprehensive unit tests for the allocator (testing out of memory, large allocations, coalescing efficiency). *(Resource: [Rust testing framework docs](https://doc.rust-lang.org/book/ch11-01-writing-tests.html))*', 'Daily DSAR rep: Arrays & String manipulation. (e.g. Reverse string, valid palindrome)'),
(13, '2026-09-25', 1, 2, 'Finish the memory allocator — free lists and alignment', 'Integrate the custom allocator into a small test binary (`#[global_allocator]`), benchmark it against the system allocator using `criterion`. *(Resource: [Criterion.rs](https://bheisler.github.io/criterion.rs/book/index.html))*', 'Daily DSAR rep: Arrays & String manipulation. (e.g. Reverse string, valid palindrome)'),
(14, '2026-09-28', 1, 2, 'Finish the memory allocator — free lists and alignment', 'Week Review & Documentation: Document the allocator''s limitations, push the code, and write a summary. Review this week''s DSAR structures instead of a new one.', 'Daily DSAR rep: Arrays & String manipulation. (e.g. Reverse string, valid palindrome)'),
(15, '2026-09-29', 1, 3, 'Finish the memory allocator — unsafe, raw pointers, wrap it up', 'Deep dive into Rust''s `UnsafeCell` and raw pointers. Refactor the `spin::Mutex` usage to properly manage interior mutability. *(Resource: [Rustonomicon: Unsafe Rust](https://doc.rust-lang.org/nomicon/))*', 'Daily DSAR rep: Linked Lists. (e.g. Reverse a linked list, detect cycle)'),
(16, '2026-09-30', 1, 3, 'Finish the memory allocator — unsafe, raw pointers, wrap it up', 'Rewrite the free list block traversal using raw pointers (`*mut u8`, `ptr::add`) to eliminate bounds checking overhead. *(Resource: [Rust std::ptr](https://doc.rust-lang.org/std/ptr/index.html))*', 'Daily DSAR rep: Linked Lists. (e.g. Reverse a linked list, detect cycle)'),
(17, '2026-10-01', 1, 3, 'Finish the memory allocator — unsafe, raw pointers, wrap it up', 'Implement custom memory mapping (`mmap` via `libc`) as the backing storage for the allocator on Unix-like systems. *(Resource: [libc mmap documentation](https://man7.org/linux/man-pages/man2/mmap.2.html))*', 'Daily DSAR rep: Linked Lists. (e.g. Reverse a linked list, detect cycle)'),
(18, '2026-10-02', 1, 3, 'Finish the memory allocator — unsafe, raw pointers, wrap it up', 'Add debugging capabilities: track allocation statistics (total allocated, total freed, peak memory usage) within the allocator state. *(Resource: [Rust Atomic types](https://doc.rust-lang.org/std/sync/atomic/))*', 'Daily DSAR rep: Linked Lists. (e.g. Reverse a linked list, detect cycle)'),
(19, '2026-10-05', 1, 3, 'Finish the memory allocator — unsafe, raw pointers, wrap it up', 'Stress test the allocator with multi-threaded workloads using `std::thread::spawn` to ensure no data races exist in the `GlobalAlloc` implementation. *(Resource: [Rust Concurrency](https://doc.rust-lang.org/book/ch16-00-concurrency.html))*', 'Daily DSAR rep: Linked Lists. (e.g. Reverse a linked list, detect cycle)'),
(20, '2026-10-06', 1, 3, 'Finish the memory allocator — unsafe, raw pointers, wrap it up', 'Finalize the crate: add `#[deny(missing_docs)]`, write module-level documentation, and publish to a local registry or GitHub. *(Resource: [Rustdoc Guide](https://doc.rust-lang.org/rustdoc/what-is-rustdoc.html))*', 'Daily DSAR rep: Linked Lists. (e.g. Reverse a linked list, detect cycle)'),
(21, '2026-10-07', 1, 3, 'Finish the memory allocator — unsafe, raw pointers, wrap it up', 'Week Review: Solidify understanding of `unsafe` boundaries and pointer arithmetic. Review this week''s DSAR structures.', 'Daily DSAR rep: Linked Lists. (e.g. Reverse a linked list, detect cycle)'),
(22, '2026-10-08', 1, 4, 'Finish rshell — process spawning, pipes, signals', 'Initialize the `rshell` binary project. Implement a basic REPL loop that reads `stdin`, parses a command, and handles `exit`. *(Resource: [Rust std::io::Stdin](https://doc.rust-lang.org/std/io/struct.Stdin.html))*', 'Daily DSAR rep: Stacks & Queues. (e.g. Valid Parentheses, Implement Queue using Stacks)'),
(23, '2026-10-09', 1, 4, 'Finish rshell — process spawning, pipes, signals', 'Implement basic process spawning using `std::process::Command`. Handle command execution and wait for the child process to finish. *(Resource: [Rust std::process](https://doc.rust-lang.org/std/process/index.html))*', 'Daily DSAR rep: Stacks & Queues. (e.g. Valid Parentheses, Implement Queue using Stacks)'),
(24, '2026-10-12', 1, 4, 'Finish rshell — process spawning, pipes, signals', 'Implement argument parsing to support commands with flags and arguments (e.g. `ls -l -a`). *(Resource: [Rust String manipulation](https://doc.rust-lang.org/book/ch08-02-strings.html))*', 'Daily DSAR rep: Stacks & Queues. (e.g. Valid Parentheses, Implement Queue using Stacks)'),
(25, '2026-10-13', 1, 4, 'Finish rshell — process spawning, pipes, signals', 'Add support for output redirection (`>`) and input redirection (`<`) by modifying the child process''s `stdout`/`stdin` via `Stdio::piped()`. *(Resource: [Rust Stdio](https://doc.rust-lang.org/std/process/struct.Stdio.html))*', 'Daily DSAR rep: Stacks & Queues. (e.g. Valid Parentheses, Implement Queue using Stacks)'),
(26, '2026-10-14', 1, 4, 'Finish rshell — process spawning, pipes, signals', 'Implement piping (`|`) between two commands by passing the `stdout` of the first command to the `stdin` of the second. *(Resource: [Pipes in Rust](https://doc.rust-lang.org/std/process/struct.ChildStdout.html))*', 'Daily DSAR rep: Stacks & Queues. (e.g. Valid Parentheses, Implement Queue using Stacks)'),
(27, '2026-10-15', 1, 4, 'Finish rshell — process spawning, pipes, signals', 'Handle Unix signals (e.g. SIGINT via Ctrl+C) using the `ctrlc` crate or `nix` to prevent the shell from exiting when a child process is interrupted. *(Resource: [ctrlc crate docs](https://docs.rs/ctrlc/latest/ctrlc/))*', 'Daily DSAR rep: Stacks & Queues. (e.g. Valid Parentheses, Implement Queue using Stacks)'),
(28, '2026-10-16', 1, 4, 'Finish rshell — process spawning, pipes, signals', 'Week Review: Document the shell architecture. Test edge cases with background processes (`&`). Review this week''s DSAR structures.', 'Daily DSAR rep: Stacks & Queues. (e.g. Valid Parentheses, Implement Queue using Stacks)'),
(29, '2026-10-19', 2, 5, 'gRPC microservice — tonic + protobuf scaffolding', 'Initialize the gRPC microservice project. Define the core `.proto` schema (e.g., a simple user service). *(Resource: [Protobuf Language Guide](https://protobuf.dev/programming-guides/proto3/))*', 'Daily DSAR rep: Hash Maps & Sets. (e.g. Two Sum, Contains Duplicate)'),
(30, '2026-10-20', 2, 5, 'gRPC microservice — tonic + protobuf scaffolding', 'Set up `tonic-build` in `build.rs` to automatically compile the `.proto` files into Rust structs and traits. *(Resource: [Tonic Build docs](https://docs.rs/tonic-build/latest/tonic_build/))*', 'Daily DSAR rep: Hash Maps & Sets. (e.g. Two Sum, Contains Duplicate)'),
(31, '2026-10-21', 2, 5, 'gRPC microservice — tonic + protobuf scaffolding', 'Implement the server stub matching the generated trait. Set up the Tokio runtime to serve the gRPC endpoint on a local port. *(Resource: [Tonic HelloWorld Example](https://github.com/hyperium/tonic/tree/master/examples/helloworld))*', 'Daily DSAR rep: Hash Maps & Sets. (e.g. Two Sum, Contains Duplicate)'),
(32, '2026-10-22', 2, 5, 'gRPC microservice — tonic + protobuf scaffolding', 'Create a simple gRPC client in a separate binary or module to test the server endpoint. *(Resource: [Tonic Client Configuration](https://docs.rs/tonic/latest/tonic/client/index.html))*', 'Daily DSAR rep: Hash Maps & Sets. (e.g. Two Sum, Contains Duplicate)'),
(33, '2026-10-23', 2, 5, 'gRPC microservice — tonic + protobuf scaffolding', 'Implement input validation within the gRPC service methods (e.g., checking for valid email formats or non-empty strings) using custom error codes (`tonic::Status`). *(Resource: [Tonic Error Handling](https://docs.rs/tonic/latest/tonic/struct.Status.html))*', 'Daily DSAR rep: Hash Maps & Sets. (e.g. Two Sum, Contains Duplicate)'),
(34, '2026-10-26', 2, 5, 'gRPC microservice — tonic + protobuf scaffolding', 'Add a structured logging middleware using `tracing` and `tracing-subscriber` to log all incoming requests and their latencies. *(Resource: [Tracing Crate](https://docs.rs/tracing/latest/tracing/))*', 'Daily DSAR rep: Hash Maps & Sets. (e.g. Two Sum, Contains Duplicate)'),
(35, '2026-10-27', 2, 5, 'gRPC microservice — tonic + protobuf scaffolding', 'Week Review: Verify the protobuf schemas are robust. Push code to repository. Review this week''s DSAR structures.', 'Daily DSAR rep: Hash Maps & Sets. (e.g. Two Sum, Contains Duplicate)'),
(36, '2026-10-28', 2, 6, 'gRPC microservice — SQLx + JWT middleware', 'Set up PostgreSQL via Docker locally. Add `sqlx` to the project and write initial migrations for the user tables. *(Resource: [SQLx CLI Migrations](https://github.com/launchbadge/sqlx/tree/main/sqlx-cli))*', 'Daily DSAR rep: Trees (Binary Search Trees). (e.g. Invert Binary Tree, Maximum Depth)'),
(37, '2026-10-29', 2, 6, 'gRPC microservice — SQLx + JWT middleware', 'Implement the database connection pool (`PgPool`) in the Tokio startup phase and share it via `tonic`''s extension or struct state. *(Resource: [SQLx Postgres Pool](https://docs.rs/sqlx/latest/sqlx/postgres/struct.PgPool.html))*', 'Daily DSAR rep: Trees (Binary Search Trees). (e.g. Invert Binary Tree, Maximum Depth)'),
(38, '2026-10-30', 2, 6, 'gRPC microservice — SQLx + JWT middleware', 'Write the CRUD operations in Rust using `sqlx::query!` macros, executing them asynchronously within the gRPC service handlers. *(Resource: [SQLx Queries](https://docs.rs/sqlx/latest/sqlx/macro.query.html))*', 'Daily DSAR rep: Trees (Binary Search Trees). (e.g. Invert Binary Tree, Maximum Depth)'),
(39, '2026-11-02', 2, 6, 'gRPC microservice — SQLx + JWT middleware', 'Implement JWT generation using the `jsonwebtoken` crate. Create a login endpoint that verifies a password (using `argon2`) and returns a token. *(Resource: [jsonwebtoken crate](https://docs.rs/jsonwebtoken/latest/jsonwebtoken/))*', 'Daily DSAR rep: Trees (Binary Search Trees). (e.g. Invert Binary Tree, Maximum Depth)'),
(40, '2026-11-03', 2, 6, 'gRPC microservice — SQLx + JWT middleware', 'Create a tonic `Interceptor` to extract the JWT from the `Authorization` metadata, validate it, and inject the user ID into the request context. *(Resource: [Tonic Interceptors](https://docs.rs/tonic/latest/tonic/service/trait.Interceptor.html))*', 'Daily DSAR rep: Trees (Binary Search Trees). (e.g. Invert Binary Tree, Maximum Depth)'),
(41, '2026-11-04', 2, 6, 'gRPC microservice — SQLx + JWT middleware', 'Write integration tests for the authenticated endpoints by spinning up a test database with `sqlx::test`. *(Resource: [sqlx::test macro docs](https://docs.rs/sqlx/latest/sqlx/macro.test.html))*', 'Daily DSAR rep: Trees (Binary Search Trees). (e.g. Invert Binary Tree, Maximum Depth)'),
(42, '2026-11-05', 2, 6, 'gRPC microservice — SQLx + JWT middleware', 'Week Review: Ensure passwords are not stored in plaintext. Review token expiration logic. Review this week''s DSAR structures.', 'Daily DSAR rep: Trees (Binary Search Trees). (e.g. Invert Binary Tree, Maximum Depth)'),
(43, '2026-11-06', 2, 7, 'gRPC microservice — Docker + health checks, ship it', 'Set up a multi-stage Dockerfile for the Rust gRPC microservice using `cargo-chef` to aggressively cache dependencies. *(Resource: [cargo-chef documentation](https://github.com/LukeMathWalker/cargo-chef))*', 'Daily DSAR rep: Tree Traversal algorithms (BFS/DFS).'),
(44, '2026-11-09', 2, 7, 'gRPC microservice — Docker + health checks, ship it', 'Implement standardized readiness and liveness health checks using the `tonic-health` crate. *(Resource: [tonic health check examples](https://github.com/hyperium/tonic/tree/master/examples/src/health))*', 'Daily DSAR rep: Tree Traversal algorithms (BFS/DFS).'),
(45, '2026-11-10', 2, 7, 'gRPC microservice — Docker + health checks, ship it', 'Implement graceful shutdown for the gRPC server by binding to Tokio''s `ctrl_c` signal handler. *(Resource: [Tokio signal handling docs](https://tokio.rs/tokio/topics/shutdown))*', 'Daily DSAR rep: Tree Traversal algorithms (BFS/DFS).'),
(46, '2026-11-11', 2, 7, 'gRPC microservice — Docker + health checks, ship it', 'Container orchestration: write a `docker-compose.yml` to spin up the gRPC service alongside a PostgreSQL database, managing secrets via `.env`. *(Resource: [Docker Compose Postgres guide](https://docs.docker.com/compose/compose-file/))*', 'Daily DSAR rep: Tree Traversal algorithms (BFS/DFS).'),
(47, '2026-11-12', 2, 7, 'gRPC microservice — Docker + health checks, ship it', 'CI/CD Pipeline: Create a GitHub Actions workflow that automatically builds the Docker image and pushes it to GitHub Container Registry (ghcr.io). *(Resource: [Building Docker images in GitHub Actions](https://docs.github.com/en/actions/publishing-packages/publishing-docker-images))*', 'Daily DSAR rep: Tree Traversal algorithms (BFS/DFS).'),
(48, '2026-11-13', 2, 7, 'gRPC microservice — Docker + health checks, ship it', 'Deploy the image to a cloud provider (e.g., Fly.io or Render) and successfully hit the live gRPC endpoint via a client. *(Resource: [Fly.io Rust deployment guide](https://fly.io/docs/languages-and-frameworks/rust/))*', 'Daily DSAR rep: Tree Traversal algorithms (BFS/DFS).'),
(49, '2026-11-16', 2, 7, 'gRPC microservice — Docker + health checks, ship it', 'Load-test the deployed gRPC service with `k6` (or a small Rust/Tokio-based concurrent client). Ramp concurrency up until you find where p99 latency and error rate start to degrade. Document the breaking point and what you''d change to push it further. *(Resource: [k6 docs](https://k6.io/docs/))*', 'Daily DSAR rep: Tree Traversal algorithms (BFS/DFS).'),
(50, '2026-11-17', 2, 7, 'gRPC microservice — Docker + health checks, ship it', 'Week Review & Documentation: Write a comprehensive README on how to run, test, and deploy the microservice. Review this week''s DSAR structures.', 'Daily DSAR rep: Tree Traversal algorithms (BFS/DFS).'),
(51, '2026-11-18', 2, 8, 'WASM — compile the ZK verifier with wasm-bindgen', 'Initialize a new Rust library (`cdylib`) and set up `wasm-bindgen` and `wasm-pack`. *(Resource: [Rust and WebAssembly book](https://rustwasm.github.io/docs/book/))*', 'Daily DSAR rep: Graphs (Representation and Traversal).'),
(52, '2026-11-19', 2, 8, 'WASM — compile the ZK verifier with wasm-bindgen', 'Extract the ZK verifier logic from the earlier project (Phase 1). Stub out the WASM-compatible struct wrappers. *(Resource: [wasm-bindgen reference](https://rustwasm.github.io/docs/wasm-bindgen/))*', 'Daily DSAR rep: Graphs (Representation and Traversal).'),
(53, '2026-11-20', 2, 8, 'WASM — compile the ZK verifier with wasm-bindgen', 'Resolve any standard library `std` or random number generator (`rand`) issues specific to WASM execution. *(Resource: [wasm-bindgen rand issue guide](https://rustwasm.github.io/docs/wasm-bindgen/reference/js-snippets.html))*', 'Daily DSAR rep: Graphs (Representation and Traversal).'),
(54, '2026-11-23', 2, 8, 'WASM — compile the ZK verifier with wasm-bindgen', 'Implement JavaScript-to-Rust serialization using `serde-wasm-bindgen` to pass verification keys and proof bytes. *(Resource: [serde-wasm-bindgen docs](https://docs.rs/serde-wasm-bindgen/latest/serde_wasm_bindgen/))*', 'Daily DSAR rep: Graphs (Representation and Traversal).'),
(55, '2026-11-24', 2, 8, 'WASM — compile the ZK verifier with wasm-bindgen', 'Expose the `verify_proof` function to JS, returning detailed error strings instead of panicking. *(Resource: [Error handling in wasm-bindgen](https://rustwasm.github.io/docs/wasm-bindgen/reference/types/result.html))*', 'Daily DSAR rep: Graphs (Representation and Traversal).'),
(56, '2026-11-25', 2, 8, 'WASM — compile the ZK verifier with wasm-bindgen', 'Write basic tests in `wasm-pack test --node` to verify the module computes proofs identically to the native binary. *(Resource: [Testing WASM](https://rustwasm.github.io/docs/wasm-pack/tutorials/npm-browser-packages/testing-your-project.html))*', 'Daily DSAR rep: Graphs (Representation and Traversal).'),
(57, '2026-11-26', 2, 8, 'WASM — compile the ZK verifier with wasm-bindgen', 'Week Review: Benchmark the WASM verification time vs Native verification time. Review this week''s DSAR structures.', 'Daily DSAR rep: Graphs (Representation and Traversal).'),
(58, '2026-11-27', 2, 9, 'WASM — TypeScript SDK wrapper, publish to npm', 'Create a TypeScript wrapper project that imports the compiled `.wasm` module. *(Resource: [TypeScript declaration files](https://www.typescriptlang.org/docs/handbook/declaration-files/introduction.html))*', 'Daily DSAR rep: Graphs (Shortest Path, e.g. Dijkstra''s Algorithm).'),
(59, '2026-11-30', 2, 9, 'WASM — TypeScript SDK wrapper, publish to npm', 'Build an ergonomic class `ZkVerifierClient` in TS that handles the raw Uint8Arrays and provides a clean API for frontends. *(Resource: [TypeScript classes](https://www.typescriptlang.org/docs/handbook/2/classes.html))*', 'Daily DSAR rep: Graphs (Shortest Path, e.g. Dijkstra''s Algorithm).'),
(60, '2026-12-01', 2, 9, 'WASM — TypeScript SDK wrapper, publish to npm', 'Implement an asynchronous WASM loader if needed (for web targets), resolving chunking or bundler configuration issues (Webpack/Vite). *(Resource: [Vite WASM plugin docs](https://vitejs.dev/guide/features.html#webassembly))*', 'Daily DSAR rep: Graphs (Shortest Path, e.g. Dijkstra''s Algorithm).'),
(61, '2026-12-02', 2, 9, 'WASM — TypeScript SDK wrapper, publish to npm', 'Write a small Next.js or React demo app that invokes the SDK to verify a dummy proof purely in the browser. *(Resource: [Next.js WebAssembly guide](https://nextjs.org/docs/app/api-reference/next-config-js/serverComponentsExternalPackages))*', 'Daily DSAR rep: Graphs (Shortest Path, e.g. Dijkstra''s Algorithm).'),
(62, '2026-12-03', 2, 9, 'WASM — TypeScript SDK wrapper, publish to npm', 'Configure GitHub Actions to automatically run `wasm-pack build`, bundle the TS SDK, and prepare the release. *(Resource: [wasm-pack build profiles](https://rustwasm.github.io/docs/wasm-pack/commands/build.html))*', 'Daily DSAR rep: Graphs (Shortest Path, e.g. Dijkstra''s Algorithm).'),
(63, '2026-12-04', 2, 9, 'WASM — TypeScript SDK wrapper, publish to npm', 'Publish the final package to the npm registry using `npm publish`, ensuring README and license are bundled. *(Resource: [npm publishing packages](https://docs.npmjs.com/packages-and-modules/contributing-packages-to-the-registry))*', 'Daily DSAR rep: Graphs (Shortest Path, e.g. Dijkstra''s Algorithm).'),
(64, '2026-12-07', 2, 9, 'WASM — TypeScript SDK wrapper, publish to npm', 'Week Review: Verify the published npm package works in a clean environment. Review this week''s DSAR structures.', 'Daily DSAR rep: Graphs (Shortest Path, e.g. Dijkstra''s Algorithm).'),
(65, '2026-12-08', 2, 10, 'First OSS/paid contribution — OnlyDust or Superteam bounty', 'Review the 2 bounty targets you pre-scoped this week on OnlyDust/Superteam (pick EZKL/SP1/Halo2-adjacent repos so the contribution stacks on what you''re already building) and commit to the most realistic one. *(Resource: [OnlyDust Platform](https://app.onlydust.xyz/))*', 'Daily DSAR rep: Dynamic Programming (1D, e.g. Climbing Stairs, Coin Change).'),
(66, '2026-12-09', 2, 10, 'First OSS/paid contribution — OnlyDust or Superteam bounty', 'Clone the repository, read the contribution guidelines (`CONTRIBUTING.md`), build the project locally, and run the test suite. *(Resource: [Rust contributing standard practices](https://rust-lang.github.io/api-guidelines/about.html))*', 'Daily DSAR rep: Dynamic Programming (1D, e.g. Climbing Stairs, Coin Change).'),
(67, '2026-12-10', 2, 10, 'First OSS/paid contribution — OnlyDust or Superteam bounty', 'Deep dive into the specific module related to the issue. Use `rg` and `rust-analyzer` to map out the execution flow. *(Resource: [Rust Analyzer features](https://rust-analyzer.github.io/manual.html))*', 'Daily DSAR rep: Dynamic Programming (1D, e.g. Climbing Stairs, Coin Change).'),
(68, '2026-12-11', 2, 10, 'First OSS/paid contribution — OnlyDust or Superteam bounty', 'Write a reproducible test case demonstrating the bug or stubbing out the new feature requirements. *(Resource: [Test-Driven Development in Rust](https://doc.rust-lang.org/book/ch11-03-test-organization.html))*', 'Daily DSAR rep: Dynamic Programming (1D, e.g. Climbing Stairs, Coin Change).'),
(69, '2026-12-14', 2, 10, 'First OSS/paid contribution — OnlyDust or Superteam bounty', 'Implement the fix/feature, adhering strictly to the project''s formatting (`cargo fmt`) and linting (`cargo clippy`) rules. *(Resource: [Clippy Lints](https://rust-lang.github.io/rust-clippy/master/index.html))*', 'Daily DSAR rep: Dynamic Programming (1D, e.g. Climbing Stairs, Coin Change).'),
(70, '2026-12-15', 2, 10, 'First OSS/paid contribution — OnlyDust or Superteam bounty', 'Submit the PR. Write a clear, detailed PR description explaining the approach, trade-offs, and how it was tested. *(Resource: [Writing a great Pull Request](https://github.blog/2015-01-21-how-to-write-the-perfect-pull-request/))*', 'Daily DSAR rep: Dynamic Programming (1D, e.g. Climbing Stairs, Coin Change).'),
(71, '2026-12-16', 2, 10, 'First OSS/paid contribution — OnlyDust or Superteam bounty', 'Week Review: Respond to any code review comments. If merged, celebrate! Review this week''s DSAR structures.', 'Daily DSAR rep: Dynamic Programming (1D, e.g. Climbing Stairs, Coin Change).'),
(72, '2026-12-17', 3, 11, 'ML primer — linear algebra refresh, forward pass of a small net', 'Review core linear algebra: Matrix multiplication, dot products, transposes. *(Resource: [3Blue1Brown Linear Algebra](https://www.youtube.com/playlist?list=PLZHQObOWTQDPD3MizzM2xVFitgF8hE_ab))*', 'Daily DSAR rep: Dynamic Programming (2D, e.g. Longest Common Subsequence).'),
(73, '2026-12-18', 3, 11, 'ML primer — linear algebra refresh, forward pass of a small net', 'Initialize a new Rust project for a from-scratch neural net. Implement a basic `Matrix` struct with naive matrix multiplication. *(Resource: [ndarray crate for reference](https://docs.rs/ndarray/latest/ndarray/))*', 'Daily DSAR rep: Dynamic Programming (2D, e.g. Longest Common Subsequence).'),
(74, '2026-12-21', 3, 11, 'ML primer — linear algebra refresh, forward pass of a small net', 'Implement basic activation functions (ReLU, Sigmoid) as standalone pure functions in Rust. *(Resource: [Understanding Activation Functions](https://towardsdatascience.com/activation-functions-neural-networks-1cbd9f8d91d6))*', 'Daily DSAR rep: Dynamic Programming (2D, e.g. Longest Common Subsequence).'),
(75, '2026-12-22', 3, 11, 'ML primer — linear algebra refresh, forward pass of a small net', 'Construct a `LinearLayer` struct with weights and biases. Write the forward pass computation. *(Resource: [Building a Neural Network from Scratch](https://nnfs.io/))*', 'Daily DSAR rep: Dynamic Programming (2D, e.g. Longest Common Subsequence).'),
(76, '2026-12-23', 3, 11, 'ML primer — linear algebra refresh, forward pass of a small net', 'Combine layers into a `Sequential` model. Feed a dummy input vector and assert the output dimensions are correct. *(Resource: [PyTorch Sequential docs for architecture design](https://pytorch.org/docs/stable/generated/torch.nn.Sequential.html))*', 'Daily DSAR rep: Dynamic Programming (2D, e.g. Longest Common Subsequence).'),
(77, '2026-12-24', 3, 11, 'ML primer — linear algebra refresh, forward pass of a small net', 'Refactor matrix multiplication to use the `ndarray` crate for highly optimized execution instead of native vectors. *(Resource: [ndarray Matrix Multiplication](https://docs.rs/ndarray/latest/ndarray/struct.ArrayBase.html#method.dot))*', 'Daily DSAR rep: Dynamic Programming (2D, e.g. Longest Common Subsequence).'),
(78, '2026-12-25', 3, 11, 'ML primer — linear algebra refresh, forward pass of a small net', 'Week Review: Ensure the forward pass matches a Python/PyTorch equivalent exactly. Review this week''s DSAR structures.', 'Daily DSAR rep: Dynamic Programming (2D, e.g. Longest Common Subsequence).'),
(79, '2026-12-28', 3, 12, 'ML primer — quantization and fixed-point arithmetic', 'Study floating point vs fixed-point representations and why ZK circuits prefer fixed-point integers over floats. *(Resource: [Fixed Point Arithmetic basics](https://en.wikipedia.org/wiki/Fixed-point_arithmetic))*', 'Daily DSAR rep: Backtracking (e.g. Permutations, N-Queens).'),
(80, '2026-12-29', 3, 12, 'ML primer — quantization and fixed-point arithmetic', 'Implement a basic `FixedPoint` wrapper struct in Rust that scales `f32` into integers using a static scale factor (e.g., $2^{16}$). *(Resource: [Rust fixed crate source](https://docs.rs/fixed/latest/fixed/))*', 'Daily DSAR rep: Backtracking (e.g. Permutations, N-Queens).'),
(81, '2026-12-30', 3, 12, 'ML primer — quantization and fixed-point arithmetic', 'Implement standard mathematical traits (`Add`, `Sub`, `Mul`) for the `FixedPoint` struct, handling overflow gracefully. *(Resource: [Rust Operator Overloading](https://doc.rust-lang.org/book/ch19-03-advanced-traits.html#default-generic-type-parameters-and-operator-overloading))*', 'Daily DSAR rep: Backtracking (e.g. Permutations, N-Queens).'),
(82, '2026-12-31', 3, 12, 'ML primer — quantization and fixed-point arithmetic', 'Quantize the weights of the previous neural network layer into fixed-point format. *(Resource: [Introduction to Neural Network Quantization](https://pytorch.org/blog/introduction-to-quantization-on-pytorch/))*', 'Daily DSAR rep: Backtracking (e.g. Permutations, N-Queens).'),
(83, '2027-01-01', 3, 12, 'ML primer — quantization and fixed-point arithmetic', 'Run the forward pass using solely integer/fixed-point arithmetic and compare the output loss/degradation relative to `f32`. *(Resource: [Quantization Error analysis](https://arxiv.org/abs/2103.13630))*', 'Daily DSAR rep: Backtracking (e.g. Permutations, N-Queens).'),
(84, '2027-01-04', 3, 12, 'ML primer — quantization and fixed-point arithmetic', 'Optimize the fixed-point operations using bit shifts instead of explicit divisions for scaling back down after multiplication. *(Resource: [Bitwise Operations in Rust](https://doc.rust-lang.org/reference/expressions/operator-expr.html#arithmetic-and-logical-binary-operators))*', 'Daily DSAR rep: Backtracking (e.g. Permutations, N-Queens).'),
(85, '2027-01-05', 3, 12, 'ML primer — quantization and fixed-point arithmetic', 'Week Review: Finalize the integer-only neural net model. Review this week''s DSAR structures.', 'Daily DSAR rep: Backtracking (e.g. Permutations, N-Queens).'),
(86, '2027-01-06', 3, 13, 'Read EZKL source — architecture and circuit design', 'Clone the `ezkl` repository. Read through the README and the architectural overview documents. *(Resource: [EZKL Documentation](https://docs.ezkl.xyz/))*', 'Daily DSAR rep: Finite field arithmetic — implement modular add/mul/inverse over a prime field by hand.'),
(87, '2027-01-07', 3, 13, 'Read EZKL source — architecture and circuit design', 'Trace the execution flow of the `ezkl gen-srs` and `ezkl setup` CLI commands. Identify the core cryptographic setup phase. *(Resource: [EZKL source code: src/cli/](https://github.com/zkonduit/ezkl))*', 'Daily DSAR rep: Finite field arithmetic — implement modular add/mul/inverse over a prime field by hand.'),
(88, '2027-01-08', 3, 13, 'Read EZKL source — architecture and circuit design', 'Investigate how EZKL parses ONNX files. Read through the `src/graph` module to understand the computation graph representation. *(Resource: [ONNX specification](https://onnx.ai/))*', 'Daily DSAR rep: Finite field arithmetic — implement modular add/mul/inverse over a prime field by hand.'),
(89, '2027-01-11', 3, 13, 'Read EZKL source — architecture and circuit design', 'Analyze the `Halo2` circuit implementation within EZKL. Identify how specific ML layers (e.g. Conv2D, Dense) are mapped to Halo2 gates. *(Resource: [Halo2 Book](https://zcash.github.io/halo2/))*', 'Daily DSAR rep: Finite field arithmetic — implement modular add/mul/inverse over a prime field by hand.'),
(90, '2027-01-12', 3, 13, 'Read EZKL source — architecture and circuit design', 'Study the layout strategy. Look at how EZKL handles variable rows and columns in the PLONKish arithmetization. *(Resource: [Plonkish Arithmetization](https://zcash.github.io/halo2/concepts/arithmetization.html))*', 'Daily DSAR rep: Finite field arithmetic — implement modular add/mul/inverse over a prime field by hand.'),
(91, '2027-01-13', 3, 13, 'Read EZKL source — architecture and circuit design', 'Read the unit tests in `tests/` specifically for simple graph verifications to see how mock provers are constructed. *(Resource: [Halo2 MockProver](https://zcash.github.io/halo2/concepts/mock_prover.html))*', 'Daily DSAR rep: Finite field arithmetic — implement modular add/mul/inverse over a prime field by hand.'),
(92, '2027-01-14', 3, 13, 'Read EZKL source — architecture and circuit design', 'Week Review: Map out the full pipeline from ONNX model to Halo2 proof on a whiteboard. Review this week''s DSAR structures.', 'Daily DSAR rep: Finite field arithmetic — implement modular add/mul/inverse over a prime field by hand.'),
(93, '2027-01-15', 3, 14, 'Read EZKL source — inference pipeline and lookup arguments', 'Deep dive into non-linear activations (ReLU, Sigmoid) in EZKL. Observe how they utilize Lookup Tables instead of raw arithmetic constraints. *(Resource: [Halo2 Lookup Arguments](https://zcash.github.io/halo2/design/proving-system/lookup.html))*', 'Daily DSAR rep: Toy polynomial commitment — implement and verify a simple Pedersen or KZG-style commitment.'),
(94, '2027-01-18', 3, 14, 'Read EZKL source — inference pipeline and lookup arguments', 'Examine how EZKL generates the evaluation points for these lookup tables during the setup phase. *(Resource: [EZKL Lookup source](https://github.com/zkonduit/ezkl/tree/main/src/circuit/table))*', 'Daily DSAR rep: Toy polynomial commitment — implement and verify a simple Pedersen or KZG-style commitment.'),
(95, '2027-01-19', 3, 14, 'Read EZKL source — inference pipeline and lookup arguments', 'Study the quantization pipeline in EZKL. Trace how input data and weights are scaled to field elements. *(Resource: [EZKL Quantization logic](https://github.com/zkonduit/ezkl/blob/main/src/tensor/var.rs))*', 'Daily DSAR rep: Toy polynomial commitment — implement and verify a simple Pedersen or KZG-style commitment.'),
(96, '2027-01-20', 3, 14, 'Read EZKL source — inference pipeline and lookup arguments', 'Review the aggregated proofs implementation (snark-verifiers or similar). How does EZKL verify a proof inside another circuit? *(Resource: [Snark Verifier architecture](https://github.com/privacy-scaling-explorations/snark-verifier))*', 'Daily DSAR rep: Toy polynomial commitment — implement and verify a simple Pedersen or KZG-style commitment.'),
(97, '2027-01-21', 3, 14, 'Read EZKL source — inference pipeline and lookup arguments', 'Analyze the performance bottlenecks. Look at how multithreading (`rayon`) is utilized in the witness generation phase. *(Resource: [Rayon documentation](https://docs.rs/rayon/latest/rayon/))*', 'Daily DSAR rep: Toy polynomial commitment — implement and verify a simple Pedersen or KZG-style commitment.'),
