-- ============================================================
-- Full Rewrite #3: Days 9-188 of the Rust Challenge
-- Restarts (2026-09-21, Monday) as Day 9. Weekdays only.
-- Split-day model: backend/Rust half of each day (Days 9-188, Weeks 2-26).
-- ============================================================

-- 1. Ensure track and subtask columns exist on rust_challenge_days
ALTER TABLE rust_challenge_days
  ADD COLUMN IF NOT EXISTS frontend_task text,
  ADD COLUMN IF NOT EXISTS system_design_task text,
  ADD COLUMN IF NOT EXISTS rust_completed boolean NOT NULL DEFAULT false,
  ADD COLUMN IF NOT EXISTS dsa_completed boolean NOT NULL DEFAULT false,
  ADD COLUMN IF NOT EXISTS frontend_completed boolean NOT NULL DEFAULT false,
  ADD COLUMN IF NOT EXISTS system_design_completed boolean NOT NULL DEFAULT false,
  ADD COLUMN IF NOT EXISTS subtasks_completed jsonb DEFAULT '[]'::jsonb;

-- 2. Update day_number check constraint to accommodate up to 188 days
ALTER TABLE rust_challenge_days DROP CONSTRAINT IF EXISTS rust_challenge_days_day_number_check;
ALTER TABLE rust_challenge_days ADD CONSTRAINT rust_challenge_days_day_number_check CHECK (day_number BETWEEN 1 AND 188);

-- 3. Safely drop challenge_date uniqueness constraint before deletion/reseed
ALTER TABLE rust_challenge_days DROP CONSTRAINT IF EXISTS rust_challenge_days_challenge_date_key;

-- 4. Delete existing days 9+ before reseeding
DELETE FROM rust_challenge_days WHERE day_number >= 9;

-- 5. Insert refined days 9 through 188 with phase and week_number

-- 6. Restore unique constraint on challenge_date
ALTER TABLE rust_challenge_days ADD CONSTRAINT rust_challenge_days_challenge_date_key UNIQUE (challenge_date);

-- 7. Notify PostgREST to reload schema cache
NOTIFY pgrst, 'reload schema';
